def _get_python_ast_hash(source: str) -> str:
    """
    Python AST结构哈希

    使用ast.dump()，include_attributes=False忽略行号等属性，
    只保留结构信息。
    """
    try:
        tree = ast.parse(source)
        # 不包含行号等属性，只关注结构
        dump = ast.dump(tree, include_attributes=False)
        return _short_hash(dump)
    except SyntaxError:
        return ""

