    """
    获取节点的装饰器列表

    参数:
        node: AST节点（类或函数）

    返回:
        装饰器名称列表
    """
    decorators = []
    for dec in getattr(node, 'decorator_list', []):
        try:
            decorators.append(ast.unparse(dec))
