    crumb.onclick = function() {{
      breadcrumbs = breadcrumbs.slice(0, i + 1);
      updateBreadcrumb();
      render(b);
    }};
    bc.appendChild(crumb);
  }});
}}

function zoomOut() {{
  breadcrumbs = [root];
  updateBreadcrumb();
  render(root);
}}

render(root);
</script>
