function buildData(filePath) {
  const nids = FILE_ANCHORS[filePath]||[];
  const nset = new Set(nids);

  // 1. class containers
  const classMap = {};          // class_nid → {id,label,methods:[]}
  const orphans  = [];          // method/fn with no class in this file
