    refreshed = []
    failed = []

    for item in drift["stale"]:
        result = refresh_anchor(item["anchor_id"], root)
        if result["status"] == "refreshed":
            refreshed.append({
                "anchor_id": item["anchor_id"],
                "old_hash": result["old_hash"],
                "new_hash": result["new_hash"],
            })
        else:
