def _subscript_string(node: ast.AST) -> str:
    if not isinstance(node, ast.Subscript):
        return ""
    value = node.slice
    if hasattr(ast, "Index") and isinstance(value, ast.Index):
        value = value.value
    if isinstance(value, ast.Constant) and isinstance(value.value, str):
        return value.value
    return ""

