def filter_anchors_by_file(keyword: str, root: str = ".") -> dict:
    """过滤文件路径包含关键词的锚点。"""
    anchors = load_anchors(root)
    kw = keyword.lower()
    result = {}
    for aid, a in anchors.items():
        f = a.file if hasattr(a, 'file') else a.get('file', '')
        if kw in f.lower():
            result[aid] = a
    return result

