def _read_current_target(project_path: str) -> Optional[Target]:
    p = _codekeeper_dir(project_path) / "current_target.json"
    if not p.exists():
        return None
    try:
        d = json.loads(p.read_text(encoding="utf-8"))
        return Target(**d)
    except Exception:
        return None

