def _split_top_level(text: str) -> List[str]:
    """按深度 0 的逗号切分参数文本"""
    parts, depth, buf = [], 0, []
    pairs = {"(": ")", "[": "]", "{": "}"}
    closers = set(pairs.values())
    stack: List[str] = []
    quote = None
    i = 0
    while i < len(text):
        ch = text[i]
        if quote:
            buf.append(ch)
            if ch == "\\":
                if i + 1 < len(text):
                    buf.append(text[i + 1])
                    i += 1
            elif ch == quote:
                quote = None
        elif ch in "'\"`":
            quote = ch
            buf.append(ch)
        elif ch in pairs:
            stack.append(pairs[ch])
            buf.append(ch)
        elif ch in closers:
            if stack and stack[-1] == ch:
                stack.pop()
            buf.append(ch)
        elif ch == "," and not stack:
            parts.append("".join(buf))
            buf = []
        else:
            buf.append(ch)
        i += 1
    if buf:
        parts.append("".join(buf))
    return parts

