def _extract_paren_text(lines: List[str], line_idx: int, start_col: int) -> str:
    """从 ( 之后开始跨行扫描，返回括号内文本"""
    depth = 1
    buf: List[str] = []
    quote = None
    li, ci = line_idx, start_col
    while li < len(lines):
        line = lines[li]
        while ci < len(line):
            ch = line[ci]
            if quote:
                if ch == "\\":
                    ci += 1
                elif ch == quote:
                    quote = None
            elif ch in "'\"`":
                quote = ch
            elif ch == "(":
                depth += 1
                buf.append(ch)
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    return "".join(buf)
                buf.append(ch)
            elif ch == "/" and ci + 1 < len(line) and line[ci + 1] == "/":
                break  # 行注释
            else:
                buf.append(ch)
            ci += 1
        li += 1
        ci = 0
    return "".join(buf)

