    """
    获取Python site-packages路径 (Medium L3-005)

    返回:
        site-packages路径列表

    对应TS: externalLibResolver.ts 的 getSitePackagesPath()

    来源:
        1. site.getsitepackages()
        2. site.getusersitepackages()
        3. sys.path中的site-packages
    """
