def validate_overrides(
    class_name: str,
    chain: List[Dict[str, Any]]
) -> List[Dict[str, Any]]:
    """
    验证方法覆盖的正确性

    参数：
        class_name: 类名
        chain: 继承链

    返回：
        验证问题列表
    """
    issues = []
    parent_methods: Set[str] = set()
    found_class = False

    for cls in chain:
        if cls["name"] == class_name:
            found_class = True
            continue

        if not found_class:
            methods = cls.get("methods", [])
            for m in methods:
                method_obj = m if isinstance(m, dict) else m
                parent_methods.add(method_obj.get("name"))

    if found_class:
        for cls in chain:
            if cls["name"] != class_name:
                break

            methods = cls.get("methods", [])
            for m in methods:
                method_obj = m if isinstance(m, dict) else m
                method_name = method_obj.get("name")

                if method_name in parent_methods:
                    if not method_obj.get("has_super", False):
                        issues.append({
                            "type": "warning",
                            "class": class_name,
                            "method": method_name,
                            "message": f"方法 {method_name} 覆盖了父类方法但没有调用 super()"
                        })

    return issues

