def find_abstract_implementations(
    class_name: str,
    chain: List[Dict[str, Any]]
) -> List[Dict[str, Any]]:
    """
    查找抽象方法的实现

    参数：
        class_name: 类名
        chain: 继承链

    返回：
        抽象方法实现列表
    """
    implementations = []
    abstract_methods = set()
    found_class = False

    for cls in chain:
        methods = cls.get("methods", [])

        for m in methods:
            method_obj = m if isinstance(m, dict) else m

            if cls["name"] == class_name:
                found_class = True

            if found_class:
                if not method_obj.get("is_abstract", False):
                    if method_obj.get("name") not in abstract_methods:
                        continue

                    implementations.append({
                        "method": method_obj.get("name"),
                        "class": cls["name"],
                        "file": cls["file"],
                        "line": method_obj.get("start", 0)
                    })
            else:
                if method_obj.get("is_abstract", False):
                    abstract_methods.add(method_obj.get("name"))

    return implementations

def find_overridden_method(
    class_name: str,
    method_name: str,
    chain: List[Dict[str, Any]]
) -> Optional[Dict[str, Any]]:
    """
    查找被覆盖的方法定义

    参数：
        class_name: 类名
        method_name: 方法名
        chain: 继承链

    返回：
        被覆盖的方法信息，如果未找到返回 None
    """
    found_current = False

    for cls in chain:
        methods = cls.get("methods", [])

        for m in methods:
            method_obj = m if isinstance(m, dict) else m
            if method_obj.get("name") == method_name:
                if found_current:
                    return {
                        "class": cls["name"],
                        "file": cls["file"],
                        "line": method_obj.get("start", 0),
                        "has_super": method_obj.get("has_super", False)
                    }

        if cls["name"] == class_name:
            found_current = True

    return None

