def _c3_merge(lists: List[List[str]]) -> List[str]:
    """C3 线性化合并"""
    import re

    result = []

    while True:
        lists = [lst for lst in lists if lst]
        if not lists:
            break

        for lst in lists:
            candidate = lst[0]
            is_good = True

            for other in lists:
                if candidate in other[1:]:
                    is_good = False
                    break

            if is_good:
                result.append(candidate)
                for lst2 in lists:
                    if candidate in lst2:
                        lst2.remove(candidate)
                break
        else:
            break

    return result

def find_method_origin(
    index: CppClassIndex,
    class_name: str,
    method_name: str
) -> Optional[CppLocation]:
    """
    查找方法定义位置

    参数：
        index: 类索引
        class_name: 类名
        method_name: 方法名

    返回：
        方法定义位置
    """
    chain = resolve_inheritance(index, class_name)

    for entry in chain:
        for method in entry.methods:
            if method.name == method_name:
                return CppLocation(
                    file=entry.file,
                    line=method.start_line
                )

    return None

